  "inlineSchema": "generator client {\n  provider      = \"prisma-client-js\"\n  binaryTargets = [\"native\", \"debian-openssl-3.0.x\"]\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nenum AuraStatus {\n  PENDING // AI generation started\n  READY // AI finished (5 avatars available)\n  ERROR // AI failed or Cloudinary failed\n}\n\nenum UserRole {\n  BUYER\n  CREATOR\n  ADMIN\n}\n\nenum ProductStatus {\n  DRAFT\n  PENDING\n  APPROVED\n  REJECTED\n  ARCHIVED\n}\n\nenum ApprovalStatus {\n  PENDING\n  APPROVED\n  REJECTED\n  ARCHIVED\n}\n\nmodel User {\n  user_id            String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  email              String   @unique\n  password_hash      String?\n  phone              String?\n  refresh_token_hash String?\n  role               UserRole @default(BUYER)\n  status             String   @default(\"active\")\n\n  // Try-on tracking (simple approach)\n  try_ons_used Int @default(0) // How many try-ons used\n  max_try_ons  Int @default(10) // Free limit\n\n  created_at DateTime  @default(now())\n  last_login DateTime?\n\n  creatorProfile      Creator?\n  approvals_submitted ProductApproval[] @relation(\"SubmittedBy\")\n  approvals_actioned  ProductApproval[] @relation(\"ActionedBy\")\n  aura                Aura?\n  product_likes       ProductLike[]\n  product_comments    ProductComment[]\n  try_on_history      TryOn[]\n}\n\nmodel Creator {\n  creator_id        String  @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  user_id           String  @unique @db.Uuid\n  store_name        String\n  store_slug        String  @unique\n  about             String?\n  verified          Boolean @default(false)\n  verification_data Json?\n\n  // Terms & Conditions tracking\n  terms_accepted    Boolean   @default(false)\n  terms_accepted_at DateTime?\n  terms_version     String?\n\n  created_at DateTime @default(now())\n\n  user     User          @relation(fields: [user_id], references: [user_id], onDelete: Cascade)\n  limits   CreatorLimit?\n  products Product[]\n}\n\nmodel CreatorLimit {\n  creator_id             String   @id @db.Uuid\n  max_products           Int      @default(100)\n  max_images_per_product Int      @default(20)\n  created_at             DateTime @default(now())\n\n  creator Creator @relation(fields: [creator_id], references: [creator_id])\n}\n\nmodel Product {\n  product_id      String        @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  creator_id      String        @db.Uuid\n  title           String\n  slug            String        @unique\n  description     String?\n  price_cents     Int\n  currency        String        @default(\"INR\")\n  inventory_count Int           @default(0)\n  category        String? // Product category (Dress, Top, Bottom, etc.)\n  is_featured     Boolean       @default(false) // Featured on homepage\n  status          ProductStatus @default(PENDING)\n  is_deleted      Boolean       @default(false)\n  max_images      Int           @default(20)\n  created_at      DateTime      @default(now())\n  updated_at      DateTime?\n\n  creator   Creator           @relation(fields: [creator_id], references: [creator_id])\n  images    ProductImage[]\n  approvals ProductApproval[]\n  stats     ProductStat?\n  likes     ProductLike[]\n  comments  ProductComment[]\n  try_ons   TryOn[]\n}\n\nmodel ProductImage {\n  image_id    String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  product_id  String   @db.Uuid\n  url         String\n  order_index Int      @default(0)\n  is_primary  Boolean  @default(false)\n  uploaded_at DateTime @default(now())\n\n  product Product @relation(fields: [product_id], references: [product_id])\n}\n\nmodel ProductApproval {\n  approval_id   String         @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  product_id    String         @db.Uuid\n  submitted_by  String?        @db.Uuid // user.user_id\n  admin_user_id String?        @db.Uuid // user.user_id\n  status        ApprovalStatus @default(PENDING)\n  comment       String?\n  created_at    DateTime       @default(now())\n  actioned_at   DateTime?\n\n  product     Product       @relation(fields: [product_id], references: [product_id])\n  submittedBy User?         @relation(\"SubmittedBy\", fields: [submitted_by], references: [user_id])\n  actionedBy  User?         @relation(\"ActionedBy\", fields: [admin_user_id], references: [user_id])\n  logs        ApprovalLog[]\n}\n\nmodel ApprovalLog {\n  log_id        String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  approval_id   String   @db.Uuid\n  actor_user_id String?  @db.Uuid\n  action        String\n  comment       String?\n  created_at    DateTime @default(now())\n\n  approval ProductApproval @relation(fields: [approval_id], references: [approval_id])\n}\n\nmodel ProductStat {\n  product_id     String    @id @db.Uuid\n  views          Int       @default(0)\n  likes_count    Int       @default(0)\n  comments_count Int       @default(0)\n  last_updated   DateTime?\n\n  product Product @relation(fields: [product_id], references: [product_id])\n}\n\nmodel ProductLike {\n  like_id    String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  product_id String   @db.Uuid\n  user_id    String   @db.Uuid\n  created_at DateTime @default(now())\n\n  product Product @relation(fields: [product_id], references: [product_id], onDelete: Cascade)\n  user    User    @relation(fields: [user_id], references: [user_id], onDelete: Cascade)\n\n  @@unique([product_id, user_id])\n  @@map(\"product_likes\")\n}\n\nmodel ProductComment {\n  comment_id   String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  product_id   String   @db.Uuid\n  user_id      String   @db.Uuid\n  comment_text String   @db.Text\n  created_at   DateTime @default(now())\n  updated_at   DateTime @updatedAt\n\n  product Product @relation(fields: [product_id], references: [product_id], onDelete: Cascade)\n  user    User    @relation(fields: [user_id], references: [user_id], onDelete: Cascade)\n\n  @@map(\"product_comments\")\n}\n\nmodel Aura {\n  aura_id String @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  user_id String @unique @db.Uuid\n\n  // User uploaded full-body image (Cloudinary)\n  image_url String?\n\n  // User-provided attributes\n  height_cm  Int?\n  weight_kg  Int?\n  skin_tone  String?\n  gender     String?\n  body_shape String?\n  age_range  String?\n  hair_style String?\n  beard      Boolean?\n\n  // Flexible extra data for AI (input or other preferences)\n  extra_attributes Json?\n\n  // ML output: prefer a single model_url (per your senior),\n  // keep generated_avatar_urls as fallback if ML returns multiples\n  model_url             String? // single model (3D render / final image)\n  generated_avatar_urls String[] @default([]) // optional array if ML returns many\n\n  // Final merged attributes / extracted attributes returned by ML\n  attributes Json? // holds ML returned attributes (height, skin tone, confidence, etc)\n\n  // PENDING → worker generating\n  // READY → model_url (or generated_avatar_urls) available\n  // ERROR → failed\n  status AuraStatus @default(PENDING)\n\n  created_at DateTime @default(now())\n  updated_at DateTime @updatedAt\n\n  user    User    @relation(fields: [user_id], references: [user_id])\n  try_ons TryOn[]\n\n  @@index([status])\n}\n\n// Simple try-on tracking\nmodel TryOn {\n  try_on_id        String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  user_id          String   @db.Uuid\n  product_id       String   @db.Uuid\n  aura_id          String   @db.Uuid\n  result_image_url String // AI generated try-on result\n  provider         String   @default(\"unknown\") // vertex or gemini\n  created_at       DateTime @default(now())\n\n  user    User    @relation(fields: [user_id], references: [user_id])\n  product Product @relation(fields: [product_id], references: [product_id])\n  aura    Aura    @relation(fields: [aura_id], references: [aura_id])\n\n  @@index([user_id])\n  @@map(\"try_ons\")\n}\n",
